 gate=fit(x,data[target+"_gain"],ss);gate.update(training_subjects=protocol["controllers"],scope_training_subjects=protocol["scope_training_subjects"],target=target,feature_count=36,scope_selection_sha256=scope_sha)
 with (o/"gates"/(target+"36.pkl")).open("wb") as f:pickle.dump(gate,f)
